<?php
namespace App\Services;
use App\Models\{AutomationLog,AutomationRule,Claim,Inventory,OrderProfit,User};use App\Notifications\BusinessAlertNotification;use Illuminate\Support\Facades\DB;
class AutomationService {
 // Creates internal alerts only; no marketplace data is changed or submitted.
 public function run(?User $requestedBy=null):array{$matched=0;$created=0;foreach(AutomationRule::where('is_active',true)->get() as $rule){foreach($this->evaluate($rule) as $a){$matched++;$fp=hash('sha256',$rule->id.'|'.$a['key']);if(AutomationLog::where('fingerprint',$fp)->exists())continue;DB::transaction(function()use($rule,$a,$fp,&$created){$log=AutomationLog::firstOrCreate(['fingerprint'=>$fp],['automation_rule_id'=>$rule->id,'severity'=>$a['severity'],'title'=>$a['title'],'message'=>$a['message'],'target_url'=>$a['url']??null,'notified_at'=>now()]);if(!$log->wasRecentlyCreated)return;foreach(User::where('is_active',true)->get() as $u){if($u->hasPermission('automation.view')||$u->hasPermission('reports.view')||$u->isSuperAdmin())$u->notify(new BusinessAlertNotification(['title'=>$a['title'],'message'=>$a['message'],'url'=>$a['url']??route('automation.index'),'severity'=>$a['severity'],'automation_log_id'=>$log->id]));}$created++;});}$rule->update(['last_run_at'=>now()]);}return ['rules'=>AutomationRule::where('is_active',true)->count(),'matched'=>$matched,'created'=>$created];}
 private function evaluate(AutomationRule $r):array{$out=[];$t=(float)$r->threshold;
 if($r->trigger_key==='low_stock'){foreach(Inventory::with('product:id,sku,name')->whereRaw('available_qty <= GREATEST(minimum_stock, ?)',[$t])->limit(200)->get() as $x)$out[]=['key'=>'stock:'.$x->product_id,'title'=>'Low stock: '.($x->product->sku??'Product'),'message'=>($x->product->name??'Product').' has '.$x->available_qty.' available units.','severity'=>'high','url'=>route('inventory.index')];}
 elseif($r->trigger_key==='claim_deadline'){foreach(Claim::whereIn('status',Claim::ALERT_STATUSES)->whereNotNull('deadline')->whereDate('deadline','<=',now()->addDays(max(0,(int)$t))->toDateString())->limit(200)->get() as $c)$out[]=['key'=>'claim:'.$c->id.':'.$c->deadline->toDateString(),'title'=>'Claim deadline: '.$c->claim_number,'message'=>'Claim '.$c->claim_number.' is '.$c->daysLeft().' day(s) from its deadline.','severity'=>$c->daysLeft()<0?'critical':'high','url'=>route('claims.show',$c)];}
 elseif($r->trigger_key==='negative_profit'){foreach(OrderProfit::where('estimated_profit','<',$t)->limit(200)->get() as $p)$out[]=['key'=>'profit:'.$p->id.':'.number_format((float)$p->estimated_profit,2,'.',''),'title'=>'Profit below threshold','message'=>'Order line #'.$p->order_item_id.' has estimated profit INR '.number_format((float)$p->estimated_profit,2).'.','severity'=>'high','url'=>route('profit.index')];}
 elseif($r->trigger_key==='high_acos'&&DB::table('advertising_daily')->where('level','CAMPAIGN')->exists()){foreach(DB::table('advertising_daily')->select('campaign_id',DB::raw('SUM(spend) spend'),DB::raw('SUM(sales) sales'))->where('level','CAMPAIGN')->groupBy('campaign_id')->havingRaw('SUM(sales)>0 AND SUM(spend)/SUM(sales)*100 > ?',[$t])->limit(100)->get() as $x)$out[]=['key'=>'acos:'.$x->campaign_id.':'.round(((float)$x->spend/(float)$x->sales)*100,2),'title'=>'High advertising ACOS','message'=>'Campaign #'.$x->campaign_id.' ACOS exceeds '.$t.'%.','severity'=>'medium','url'=>route('ads.index')];}
 return $out;}
}
